import unittest

from dateparse import core


class CoreTest(unittest.TestCase):
    def test_is_leap(self):
        self.assertTrue(core.is_leap(2000))
        self.assertFalse(core.is_leap(1900))
        self.assertTrue(core.is_leap(2024))

    def test_parse_iso_date(self):
        self.assertEqual(core.parse_iso_date("2024-02-29"), (2024, 2, 29))
        with self.assertRaises(ValueError):
            core.parse_iso_date("2023-02-29")

    def test_day_of_year(self):
        self.assertEqual(core.day_of_year(2023, 3, 1), 60)

    def test_april(self):
        self.assertEqual(core.days_in_month(2023, 4), 30)

    def test_format_iso(self):
        self.assertEqual(core.format_iso(7, 3, 9), "0007-03-09")

    def test_weekday(self):
        self.assertEqual(core.weekday(2024, 1, 1), 0)

    def test_parse_strip(self):
        self.assertEqual(core.parse_iso_date(" 1999-12-31 "), (1999, 12, 31))

    def test_add_days(self):
        self.assertEqual(core.add_days(2023, 12, 30, 3), (2024, 1, 2))

    def test_bad_month(self):
        with self.assertRaises(ValueError):
            core.parse_iso_date("2020-13-01")

    def test_is_weekend(self):
        self.assertTrue(core.is_weekend(2024, 1, 6))

    def test_leap_1600(self):
        self.assertTrue(core.is_leap(1600))
